def country_of(s):
    if s is None or s.strip() == '':
        return None
    k = s.strip().lower()
    if k not in COUNTRY:
        raise KeyError('unmapped country: ' + repr(s))
    return COUNTRY[k]

CC_OF = {'1': 'US', '31': 'NL', '32': 'BE', '33': 'FR', '34': 'ES', '39': 'IT', '41': 'CH', '43': 'AT',
         '44': 'GB', '45': 'DK', '46': 'SE', '47': 'NO', '49': 'DE', '52': 'MX', '61': 'AU', '81': 'JP', '353': 'IE'}
TRUNK0 = {'GB', 'IE', 'AU', 'DE', 'AT', 'CH', 'FR', 'BE', 'NL', 'JP', 'SE'}
CC_LEN_ORDER = ['353', '31', '32', '33', '34', '39', '41', '43', '44', '45', '46', '47', '49', '52', '61', '81', '1']

def split_cc(digits):
    for cc in CC_LEN_ORDER:
        if digits.startswith(cc):
            return cc, digits[len(cc):]
    raise ValueError('no calling code: ' + digits)

def norm_phone(raw, row_country, bd=False):
    if raw is None:
        return None
    s = raw.strip()
    if s in PLACEHOLDERS or re.fullmatch(r'[\s\-0]*', s):
        return None
    s = s.replace('(0)', '')
    intl = False
    if s.startswith('+'):
        intl, s = True, s[1:]
    elif s.startswith('00'):
        intl, s = True, s[2:]
    elif bd and s.startswith('011'):
        intl, s = True, s[3:]
    digits = re.sub(r'\D', '', s)
    if intl:
        cc, nat = split_cc(digits)
        ctry = CC_OF[cc]
    else:
        cc = {v: k for k, v in CC_OF.items() if k != '1'}[row_country] if row_country != 'US' and row_country != 'CA' else '1'
        nat = digits
        ctry = row_country
    if ctry in TRUNK0 and nat.startswith('0'):
        nat = nat[1:]
    return '+' + cc + nat

def parse_dmy_dot(s):
    s = s.strip()
    if s in PLACEHOLDERS:
        return None
    d, m, y = s.split('.')
    return date(int(y), int(m), int(d))

def parse_named_date(s):
    s = s.strip()
    for fmt in ('%d %b %Y', '%d-%b-%Y', '%d %B %Y', '%B %d, %Y'):
        try:
            return datetime.strptime(s, fmt).date()
        except ValueError:
            pass
    raise ValueError('bad date ' + s)

class Row:
    def __init__(self, sys, rid, given='', family='', dob=None, country=None, phone=None,
                 bal=None, ccy=None, upd=None, void=False):
        self.sys, self.rid, self.given, self.family = sys, rid, given, family
        self.dob, self.country, self.phone, self.bal, self.ccy = dob, country, phone, bal, ccy
        self.upd, self.void = upd, void
    def __repr__(self):
        return f'{self.sys}{self.rid}'

TITLES = {'mr', 'mrs', 'ms', 'dr', 'prof', 'herr', 'frau'}
def is_title(t):
    return t.rstrip('.').lower() in TITLES
def is_init(t):
    return len(t.rstrip('.')) == 1

# ---------- BRIGHTDESK ----------
def split_bd_name(s):
    s = s.strip()
    if ',' in s:
        fam, giv = s.split(',', 1)
        g = [t for t in giv.split() if not is_title(t) and not is_init(t)]
        return ' '.join(g), fam.strip()
    toks = [t for t in s.split() if not is_title(t) and not is_init(t)]
    fam = [t for t in toks if t.isupper()]
    giv = [t for t in toks if not t.isupper()]
    return ' '.join(giv), ' '.join(fam)

def parse_bd(line):
    parts = [p.strip() for p in line.split(' | ')]
    rid = int(re.search(r'row=(\d+)', parts[0]).group(1))
    kv = {}
    for p in parts[1:]:
        if '=' in p:
            k, v = p.split('=', 1)
            kv[k.strip()] = v.strip()
    void = kv['name'].startswith('ZZTEST')
    given, family = split_bd_name(kv['name'])
    m = re.fullmatch(r'(\d{1,2})/(\d{1,2})/(\d{4})', kv['dob'])
    dob = date(int(m[3]), int(m[2]), int(m[1])) if m else parse_named_date(kv['dob'])
    country = country_of(kv['country'])
    phone = norm_phone(kv['phone'], country, bd=True)
    bal = None
    if re.search(r'\d', kv['balance']):
        v = kv['balance']
        neg = v.startswith('(') or '-' in v
        printed = Decimal(re.sub(r'[^\d.]', '', v))
        if neg:
            printed = -printed
        bal = -printed  # BRIGHTDESK prints the opposite sign to the master
    upd = date.fromisoformat(kv['updated'])
    return Row('BD', rid, given, family, dob, country, phone, bal, 'USD', upd, void)

# ---------- ATLAS ----------
def split_atlas_name(s):
    s = re.sub(r'\([^)]*\)', '', s).strip()
    if ',' in s:
        fam, giv = s.split(',', 1)
        g = [t for t in giv.split() if not is_title(t) and not is_init(t)]
        return ' '.join(g), fam.strip()
    toks = [t for t in s.split() if not is_title(t)]
    giv = toks[0]
    fam = ' '.join(t for t in toks[1:] if not is_init(t))
    return giv, fam

def parse_atlas(line):
    segs = [s.strip() for s in line.split(' :: ')]
    rid = int(re.search(r'#(\d+)', segs[0]).group(1))
    void = segs[-1] in ('DORMANT', 'DO NOT MIGRATE')
    def field(prefix):
        for s in segs:
            if s == prefix or s.startswith(prefix + ' '):
                return s[len(prefix):].strip()
        return ''
    upd = parse_named_date(field('last change'))
    born = field('born')
    if born in ('?', 'n/k', ''):
        dob = None
    else:
        m = re.fullmatch(r'(\d{1,2})/(\d{1,2})/(\d{4})', born)
        if m:
            a, b, y = int(m[1]), int(m[2]), int(m[3])
            mo, d = (a, b) if upd >= date(2021, 10, 2) else (b, a)
            dob = date(y, mo, d)
        else:
            dob = parse_named_date(born)
    country = country_of(segs[3])
    phone = norm_phone(field('tel'), country)
    owed = field('owed')
    bal = None
    if re.search(r'\d', owed):
        cr = owed.endswith('CR')
        val = Decimal(re.sub(r'[^\d.]', '', owed.replace(',', '')))
        owed_val = -val if cr else val
        bal = -owed_val  # positive owed = our debt = negative master balance
    given, family = split_atlas_name(segs[1])
    return Row('ATLAS', rid, given, family, dob, country, phone, bal, 'GBP', upd, void)

# ---------- LEDGR ----------
def parse_ledgr(line):
    f = [x.strip() for x in line.split(';')]
    rid = int(f[1])
    void = f[8] == 'storniert'
    fam, giv = [x.strip() for x in f[2].split(',', 1)]
    dob = parse_dmy_dot(f[4])
    country = country_of(f[5])
    phone = norm_phone(f[6], country)
    bal, ccy = None, None
    if re.search(r'\d', f[7]):
        ccy = 'CHF' if 'CHF' in f[7] else 'EUR'
        neg = '-' in f[7]
        val = Decimal(re.sub(r'[^\d.,]', '', f[7]).replace('.', '').replace(',', '.'))
        bal = -val if neg else val
    upd = parse_dmy_dot(f[9])
    return Row('LEDGR', rid, giv, fam, dob, country, phone, bal, ccy, upd, void)

# ---------- KOBO ----------
def parse_kobo_birth(v):
    v = v.strip()
    if not v:
        return None
    m = re.fullmatch(r'([HS])(\d+)\.(\d{1,2})\.(\d{1,2})', v)
    if m:
        base = 1988 if m[1] == 'H' else 1925
        return date(base + int(m[2]), int(m[3]), int(m[4]))
    m = re.fullmatch(r'(\d{4})/(\d{1,2})/(\d{1,2})', v)
    return date(int(m[1]), int(m[2]), int(m[3]))

def parse_kobo(line):
    head, *rest = [p.strip() for p in line.split(' | ')]
    rid = int(re.search(r'KOBO/(\d+)', head).group(1))
    name = head.split('member:', 1)[1].strip()
    kv = {}
    for p in rest:
        k, _, v = p.partition(':')
        kv[k.strip()] = v.strip()
    void = 'flag: SAMPLE' in rest or 'flag: GIFT' in rest
    fam, giv = name.split(' ', 1)
    dob = parse_kobo_birth(kv.get('birth', ''))
    phone = norm_phone(kv.get('tel', ''), 'JP')
    v = kv['balance']
    neg = '▲' in v or '-' in v
    printed = Decimal(re.sub(r'\D', '', v))
    if neg:
        printed = -printed
    bal = -printed  # KOBO balances change sign in the master
    upd = date(*[int(x) for x in kv['upd'].split('/')])
    return Row('KOBO', rid, giv, fam, dob, 'JP', phone, bal, 'JPY', upd, void)

# ---------- VERITAS ----------
def parse_veritas(line):
    o = json.loads(line[len('VERITAS '):])
    rid = o['row']
    void = o.get('env') == 'sandbox'
    dob = None if (not o.get('dob') or o['dob'] == '1900-01-01') else date.fromisoformat(o['dob'])
    country = country_of(o['country']) if o.get('country') else None
    phone = '+' + re.sub(r'\D', '', o['msisdn']) if o.get('msisdn') else None
    bal = Decimal(o['amount']) if o.get('amount') not in (None, '') else None
    ccy = o.get('ccy')
    upd = datetime.fromisoformat(o['ts'].replace('Z', '+00:00')).date()
    return Row('VERITAS', rid, o['given'], o['family'], dob, country, phone, bal, ccy, upd, void)

