def nick(g):
    return NICK.get(g.lower(), g)

def fold(s):
    s = s.replace('ß', 'ss').replace('Ø', 'O').replace('ø', 'o').replace('Æ', 'AE').replace('æ', 'ae')
    s = unicodedata.normalize('NFKD', s)
    return ''.join(c for c in s if not unicodedata.combining(c))

def key_part(s):
    return fold(s).lower().replace(' ', '').replace("'", '').replace('.', '')

def osa(a, b):
    n, m = len(a), len(b)
    d = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        d[i][0] = i
    for j in range(m + 1):
        d[0][j] = j
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            d[i][j] = min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + cost)
            if i > 1 and j > 1 and a[i - 1] == b[j - 2] and a[i - 2] == b[j - 1]:
                d[i][j] = min(d[i][j], d[i - 2][j - 2] + 1)
    return d[n][m]

def names_match(a, b):
    return osa(key_part(nick(a.given)), key_part(nick(b.given))) + osa(key_part(a.family), key_part(b.family)) <= 1

def same_person(a, b):
    if a.dob and b.dob:
        return a.dob == b.dob and names_match(a, b)
    return names_match(a, b) and a.phone is not None and a.phone == b.phone

# ---------- grouping ----------
