parent = {r.rid: r.rid for r in live}
def find(x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]
        x = parent[x]
    return x
pairs = []
for i, a in enumerate(live):
    for b in live[i + 1:]:
        if same_person(a, b):
            pairs.append((a.rid, b.rid))
            parent[find(a.rid)] = find(b.rid)
