    groups.setdefault(find(r.rid), []).append(r)

# ---------- conversion ----------
RATE = {'USD': (None, None), 'EUR': ('*', '1.0625'), 'GBP': ('*', '1.2322'), 'AUD': ('*', '0.6298'),
        'JPY': ('/', '152.7884'), 'CHF': ('/', '0.9327'), 'CAD': ('/', '1.3976'), 'SEK': ('/', '10.6453'),
        'DKK': ('/', '6.9931'), 'NOK': ('/', '10.9686'), 'MXN': ('/', '17.4213')}

def to_usd(amt, ccy):
    op, rate = RATE[ccy]
    if op is None:
        v = amt
    elif op == '*':
        v = amt * Decimal(rate)
    else:
        v = amt / Decimal(rate)
    return v.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

def order_key(r):
    # BRIGHTDESK updated dates are restamped, so those rows come after the others
    return (1 if r.sys == 'BRIGHTDESK' else 0, -r.upd.toordinal())

def accent_restore(val, others, get):
    if all(ord(c) < 128 for c in val):
        for o in others:
            cand = get(o)
            if cand != val and any(ord(c) > 127 for c in cand) and fold(cand).lower() == val.lower():
                return cand
    return val

out = []
for root, grp in sorted(groups.items(), key=lambda kv: min(r.rid for r in kv[1])):
