    first = g[0]
    given = nick(first.given)
    family = first.family
    given = accent_restore(given, g, lambda r: nick(r.given))
    family = accent_restore(family, g, lambda r: r.family)
    if family.isupper():
        family = ' '.join(w.capitalize() for w in family.split(' '))
    dob = next((r.dob for r in g if r.dob), None)
    country = next((r.country for r in g if r.country), None)
    phone = next((r.phone for r in g if r.phone), None)
    withbal = next((r for r in g if r.bal is not None), None)
    usd = to_usd(withbal.bal, withbal.ccy) if withbal else None
    out.append({
        'entity_id': min(r.rid for r in grp),
        'source_rows': sorted(r.rid for r in grp),
        'given_name': given,
        'family_name': family,
        'birth_date': dob.isoformat() if dob else None,
        'country': country,
        'phone_e164': phone,
        'amount_usd': float(usd) if usd is not None else None,
        '_dbg': [(r.sys, r.rid, str(r.upd), r.country, r.phone, str(r.bal), r.ccy) for r in g],
